 931	/// Activate the inspector. This will begin collecting inspection data.
 932	/// This will not affect the GUI. The GUI must use performAction to
 933	/// show/hide the inspector UI.
 934	pub fn activateInspector(self: *Surface) !void {
 935	    if (self.inspector != null) return;
2750	    event_orig: input.KeyEvent,
2751	) ?input.Binding.Flags {
2752	    // Apply key remappings for consistency with keyCallback
2753	    var event = event_orig;
2754	    if (self.config.key_remaps.isRemapped(event_orig.mods)) {
2755	        event.mods = self.config.key_remaps.apply(event_orig.mods);
2756	    }
2757	
2758	    switch (event.action) {
2759	        .release => return null,
2760	        .press, .repeat => {},
2761	    }
2762	
2763	    // Look up our entry
2764	    const entry: input.Binding.Set.Entry = entry: {
2765	        // If we're in a sequence, check the sequence set
2766	        if (self.keyboard.sequence_set) |set| {
2767	            break :entry set.getEvent(event) orelse return null;
2768	        }
2769	
2770	        // Check active key tables (inner-most to outer-most)
2771	        const table_items = self.keyboard.table_stack.items;
2772	        for (0..table_items.len) |i| {
2773	            const rev_i: usize = table_items.len - 1 - i;
2774	            if (table_items[rev_i].set.getEvent(event)) |entry| {
2775	                break :entry entry;
2776	            }
2777	        }
2778	
2779	        // Check the root set
2780	        break :entry self.config.keybind.set.getEvent(event) orelse return null;
2781	    };
2782	
2783	    // Return flags based on the
2784	    return switch (entry.value_ptr.*) {
2785	        .leader => .{},
2786	        inline .leaf, .leaf_chained => |v| v.flags,
2787	    };
2788	}
