3221	fn deactivateAllKeyTables(self: *Surface) !bool {
3222	    switch (self.keyboard.table_stack.items.len) {
3223	        // No key table active. This does nothing.
3224	        0 => return false,
3225	
3226	        // Clear the entire table stack.
3227	        else => self.keyboard.table_stack.clearAndFree(self.alloc),
3228	    }
3229	
3230	    // Notify the UI.
3231	    _ = self.rt_app.performAction(
3232	        .{ .surface = self },
3233	        .key_table,
3234	        .deactivate_all,
3235	    ) catch |err| {
3236	        log.warn(
3237	            "failed to notify app of key table err={}",
3238	            .{err},
3239	        );
3240	    };
3241	
3242	    return true;
3243	}
